package com.asmj.marketplace.service.repository;import com.asmj.marketplace.service.model.ProviderSchedule;import org.springframework.data.mongodb.repository.MongoRepository;import java.time.DayOfWeek;import java.util.*;public interface ProviderScheduleRepository extends MongoRepository<ProviderSchedule,String>{List<ProviderSchedule> findByServiceIdAndDayOfWeekAndActiveTrue(String serviceId,DayOfWeek day);List<ProviderSchedule> findByVendorIdOrderByDayOfWeekAscStartTimeAsc(String vendorId);}
